const UPI_ID='7081201212@fam';
function checkout(){if(!lines().length)return;closeModal();go('checkout')}
function paymentPage(){if(!lines().length)return '<h1>YOUR CART IS EMPTY</h1><button class="btn-primary" data-view="shop">EXPLORE FIGURES</button>';return `<p class="trust-proof">CART → DELIVERY → PAYMENT</p><h1>COMPLETE YOUR ORDER</h1><form onsubmit="placeOrder(event)" class="payment-layout"><div><section class="payment-box"><h2>01 · Delivery details</h2><div class="ak-form">${fields()}</div></section><section class="payment-box"><h2>02 · Payment method</h2><label class="payment-option"><input type="radio" name="payment" value="cod" checked onchange="selectPayment(this.value)"><span><strong>Cash on Delivery</strong><small>Pay when your order arrives, after the seller confirms delivery availability.</small></span><b>COD</b></label><label class="payment-option"><input type="radio" name="payment" value="upi" onchange="selectPayment(this.value)"><span><strong>UPI payment</strong><small>Use any compatible UPI app.</small></span><b>UPI</b></label><div id="upi-panel" hidden><p>Pay to this UPI ID</p><div class="upi-address"><strong>${UPI_ID}</strong><button class="btn-outline" type="button" onclick="copyUpi()">COPY ID</button></div><p>Amount: <strong>${INR(totals().total)}</strong></p><div style="text-align:center;margin:22px 0"><img src="data:image/svg+xml;base64," alt="Scan to pay Anime Kingdom at 7081201212@fam using UPI" width="280" height="280" style="display:block;background:white;border:12px solid white;border-radius:12px;margin:0 auto;max-width:100%;height:auto"><p><strong>SCAN & PAY WITH UPI</strong><br>Enter the checkout total shown above in your UPI app.</p></div><a class="btn-primary" href="${E('upi://pay?pa='+encodeURIComponent(UPI_ID)+'&pn=Anime%20Kingdom&am='+totals().total.toFixed(2)+'&cu=INR&tn=Anime%20Kingdom%20order')}">OPEN UPI APP ↗</a><p class="form-help">Verify the recipient in your UPI app before approving. Opening the app does not confirm payment. On desktop, enter the ID and amount in your phone’s UPI app.</p><label class="payment-reference">UTR / UPI transaction number<input id="upi-utr" name="upiReference" inputmode="numeric" pattern="[0-9]{12}" maxlength="12" placeholder="12-digit UTR from your UPI app" disabled></label><label class="payment-reference">Payment screenshot<input id="upi-proof" name="upiScreenshot" type="file" accept="image/png,image/jpeg,image/webp" onchange="previewPaymentProof(this)" disabled></label><p class="form-help">Upload a PNG, JPG or WebP image (maximum 2 MB). Your UTR and screenshot are sent privately to Anime Kingdom for verification.</p><img id="upi-proof-preview" hidden alt="Selected payment screenshot" style="max-width:100%;max-height:300px;border-radius:8px"><p class="form-help">Payment stays unverified until the seller checks it. A reference number is not proof of payment.</p></div></section></div><aside class="payment-box payment-summary"><h2>Order summary</h2>${lines().map(({p,qty})=>`<article class="cart-row"><img src="${photo(p)}" alt="${E(p.name)}"><div><h3>${E(p.name)}</h3><p>${quantityLabel(p,qty)}</p></div><strong>${INR(p.price*qty)}</strong></article>`).join('')}${summary()}<p class="form-help">Your order, address and payment proof are sent to Anime Kingdom. Submission is confirmed only after the database saves it. Payment verification and delivery confirmation are handled by the seller.</p><button class="btn-primary" style="width:100%" id="payment-submit">PLACE COD ORDER</button><button type="button" class="text-button" onclick="openCart()">Edit cart</button></aside></form>`}
function selectPayment(method){for(const id of ['upi-utr','upi-proof']){$(id).disabled=method!=='upi';$(id).required=method==='upi'}$('upi-panel').hidden=method!=='upi';$('payment-submit').textContent=method==='upi'?'SUBMIT ORDER · VERIFICATION PENDING':'PLACE COD ORDER'}
async function copyUpi(){try{await navigator.clipboard.writeText(UPI_ID);toast('UPI ID copied.')}catch{toast('Copy this UPI ID: '+UPI_ID)}}

function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const stages=['Order Placed','Confirmed','Processing','Packed','Shipped','Out for Delivery','Delivered','Cancelled'];
function fields(){return [['name','Full name','text'],['email','Email','email'],['phone','Indian mobile number','tel'],['address','Address','text'],['city','City','text'],['state','State / union territory','text'],['pin','PIN code','text']].map(([k,l,t])=>`<label>${l}<input name="${k}" type="${t}" required maxlength="300" ${k==='phone'?'pattern="[6-9][0-9]{9}" title="10-digit Indian mobile number"':k==='pin'?'pattern="[1-9][0-9]{5}" title="6-digit PIN code"':''} value="${E(state.profile[k])}"></label>`).join('')}
function orderDate(value){const date=new Date(value);if(!Number.isFinite(date.getTime()))return 'Date unavailable';return new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kolkata'}).format(date)+' · '+new Intl.DateTimeFormat('en-IN',{hour:'numeric',minute:'2-digit',hour12:true,timeZone:'Asia/Kolkata'}).format(date)+' IST'}
function orderCard(o){return `<article class="saved-order"><h2>Thank you for your order!</h2><p>${E(orderDate(o.date))}</p>${o.items.map(i=>`<p>${E(i.name)} × ${i.qty} · ${INR(i.price*i.qty)}</p>`).join('')}<strong>${INR(o.total)}</strong>${o.upiReference?`<p>UPI reference: ${E(o.upiReference)} (unverified)</p>`:''}${/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(o.paymentScreenshot||'')?`<details><summary>View payment screenshot</summary><img src="${o.paymentScreenshot}" alt="Payment screenshot" style="max-width:100%;max-height:400px;margin-top:15px"></details>`:''}</article>`}

function invoice(id){const o=state.orders.find(o=>o.id===id);download(o.id+'.html',`<!doctype html><html lang="en"><meta charset="utf-8"><title>${E(o.id)}</title><style>body{font:16px Arial;max-width:850px;margin:40px auto;padding:20px;line-height:1.7}td,th{padding:12px;border-bottom:1px solid #ddd;text-align:left}table{width:100%}</style><img src="${ASSETS.logo}" width="90" alt="Anime Kingdom"><h1>ANIME KINGDOM</h1><h2>${o.cloudSaved?'ORDER RECEIPT — NOT A TAX INVOICE':'LOCAL TEST ORDER — NOT A TAX INVOICE'}</h2><p>${E(o.id)} · ${E(o.date)}</p><p>${E(o.paymentMethod==='upi'?'UPI payment unverified.':'Payment due on delivery.')} ${o.cloudSaved?'Order received in Anime Kingdom database; seller confirmation required.':'Order saved locally only; not submitted.'}</p><h3>Billing & shipping</h3><p>${Object.values(o.address).map(E).join('<br>')}</p><table><tr><th>Product</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr>${o.items.map(i=>`<tr><td>${E(i.name)}</td><td>${i.packSize>1?i.qty+' pack(s) · '+i.pieces+' pieces':i.qty}</td><td>${INR(i.price)}</td><td>${INR(i.qty*i.price)}</td></tr>`).join('')}</table><p>Subtotal ${INR(o.subtotal)}<br>Discount ${INR(o.discount)}<br>Demo shipping ${INR(o.shipping)}<br>GST: not configured<br><b>Total ${INR(o.total)}</b></p><p>Use your browser’s Print → Save as PDF to create a PDF.</p></html>`,'text/html')}
function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
function customPage(){return `<h1>CUSTOM 3D FIGURES</h1><p>Send your concept brief to Anime Kingdom for review. A custom request is not a confirmed purchase.</p><aside class="custom-contact"><h2>Let’s Create Your Custom 3D Figure</h2><p>Share your inspiration, reference photos, and preferred style with us. Contact <a href="https://www.instagram.com/animekingdom_store/" target="_blank" rel="noopener">@animekingdom_store</a> on Instagram or WhatsApp us at <a href="https://wa.me/917081201212" target="_blank" rel="noopener">7081201212</a> to discuss your custom figure.</p><p><a class="btn-outline" style="border-color:#ff4545;margin:8px 8px 8px 0" href="https://www.youtube.com/@Animekingdom_store" target="_blank" rel="noopener">SUBSCRIBE ON YOUTUBE ↗</a></p><div class="account-actions"><a class="btn-outline" href="https://ig.me/m/animekingdom_store" target="_blank" rel="noopener">CONTACT ON INSTAGRAM</a><a class="btn-primary" href="https://wa.me/917081201212" target="_blank" rel="noopener">MESSAGE ON WHATSAPP</a></div></aside><form class="ak-form" onsubmit="saveCustom(event)"><label>Full name<input name="name" required maxlength="300"></label><label>Email<input name="email" type="email" required maxlength="320"></label><label>Phone<input name="phone" type="tel" required pattern="[6-9][0-9]{9}"></label><label>Instagram ID (optional)<input name="instagram_id" placeholder="@your_username" maxlength="31" autocomplete="off" spellcheck="false"></label><label>Character / style<input name="character" required maxlength="150"></label><label>Size<select name="size">${opts(['Mini figure','18 cm','30 cm','50 cm','Bust','Discuss size'],'18 cm')}</select></label><label>Pose<input name="pose" required maxlength="200"></label><label>Accessories<input name="accessories" maxlength="300"></label><label>Finish<select name="finish">${opts(['Full color','Metallic accents','Unpainted DIY'],'Full color')}</select></label><label>Reference image<input name="reference" type="file" accept="image/png,image/jpeg,image/webp"></label><label class="wide">Special requirements<textarea name="requirements" required maxlength="3000"></textarea></label><button class="btn-primary wide">SUBMIT CUSTOM REQUEST</button></form>`}
function exportBrief(id){download('anime-kingdom-custom-brief.json',JSON.stringify(state.requests.find(r=>r.id===id),null,2))}
function tick(){let text='DATE TO BE ANNOUNCED';const ms=Date.parse(state.dropDate)-Date.now();if(state.dropDate&&Number.isFinite(ms)){const s=Math.max(0,Math.floor(ms/1000));text=ms<=0?'THE COUNTDOWN HAS ENDED':Math.floor(s/86400)+'d '+String(Math.floor(s/3600)%24).padStart(2,'0')+'h '+String(Math.floor(s/60)%60).padStart(2,'0')+'m '+String(s%60).padStart(2,'0')+'s'}for(const id of ['countdown','page-countdown'])if($(id))$(id).textContent=text}
const policies={shipping:'Shipping charges, delivery estimates, returns, exchanges, cancellations, pre-orders and damaged-item procedures have not been configured. This demo creates no shipments. Confirm final policies before a real purchase.',privacy:'Submitted orders, contact details, addresses, custom briefs, UTR numbers and payment screenshots are stored privately in Anime Kingdom’s Supabase database. Cart, wishlist and receipt copies are kept on this device. Never enter card details, passwords or UPI PINs. Contact the store for data removal.',terms:'Submitted orders are pending seller review. Catalog prices and stock are samples until confirmed by the store. UPI transfers are made in your payment app and require manual verification. Delivery and final business terms require seller confirmation.'};
function renderPage(){let h='';switch(activeView){case 'checkout':h=paymentPage();break;case 'shop':case 'wishlist':h=shop();break;case 'collections':h='<h1>EXPLORE COLLECTIONS</h1><div class="products-grid">'+[...new Set(state.products.map(p=>p.anime))].map(n=>{const p=state.products.find(p=>p.anime===n);return `<article class="product-card"><img class="detail-photo" style="height:280px" src="${photo(p)}" alt="${E(n)}"><div class="product-body"><h2>${E(n)}</h2><p>${state.products.filter(p=>p.anime===n).length} demo products</p><button class="btn-primary" data-collection="${E(n)}">VIEW COLLECTION</button></div></article>`}).join('')+'</div>';break;case 'custom':h=customPage();break;case 'orders':h='<h1>MY ORDERS</h1><p>New orders are submitted to Anime Kingdom. This page shows your receipts on this device.</p>'+(state.orders.map(orderCard).join('')||'<p>No test orders yet.</p>');break;case 'account':h=`<h1>CUSTOMER DETAILS</h1><p>Send your contact and delivery details to Anime Kingdom. This form does not create a login account.</p><div class="account-actions"><button class="btn-outline" data-view="orders">MY TEST ORDERS</button><button class="btn-outline" data-view="wishlist">WISHLIST</button><button class="btn-outline" data-view="custom">CUSTOM BRIEFS</button></div><form class="ak-form" onsubmit="saveProfile(event)">${fields()}<button class="btn-primary wide">SAVE CUSTOMER DETAILS</button></form>`;break;case 'drops':h='<h1>NEW DROPS</h1><div id="page-countdown" class="drop-empty"></div><p>Set a date in the local editor to preview the countdown. Follow Instagram and YouTube for published announcements.</p><a class="btn-outline" href="https://www.instagram.com/animekingdom_store/" target="_blank" rel="noopener">FOLLOW ON INSTAGRAM ↗</a><a class="btn-outline" style="border-color:#ff4545;margin:8px 8px 8px 0" href="https://www.youtube.com/@Animekingdom_store" target="_blank" rel="noopener">SUBSCRIBE ON YOUTUBE ↗</a><div class="products-grid">'+state.products.filter(p=>p.new).map(card).join('')+'</div>';break;case 'kingdom':h='<h1>THE ANIME KINGDOM</h1><p>Explore the Anime Kingdom showroom and discover your next collectible.</p><div class="process-grid">'+[['THE ENTRANCE','home'],['FIGURE HALL','shop'],['PREMIUM GALLERY','collections'],['CUSTOM WORKSHOP','custom'],['NEW DROP VAULT','drops']].map(([n,v])=>`<article><h3>${n}</h3><button class="btn-outline" data-view="${v}">ENTER →</button></article>`).join('')+'</div>';break;case 'workshop':h='<h1>OUR WORKSHOP</h1><div class="process-grid">'+[['SCULPT','Develop the character and pose.'],['MODEL','Prepare the form and details.'],['PRINT','Build the physical shape.'],['PAINT','Explore colors and finishes.'],['CHECK','Review against the brief.'],['PACK','Protect the finished piece.']].map(([n,p])=>`<article><h3>${n}</h3><p>${p}</p></article>`).join('')+'</div><p>This describes an intended workflow. Confirm production details with the store.</p>';break;case 'about':h='<h1>WELCOME TO ANIME KINGDOM</h1><div class="workshop-grid"><div><h2>YOUR FANDOM, ON DISPLAY.</h2><p>A place for character-inspired figures, collectibles and custom concepts. Explore anime and superhero pieces, or start with an idea of your own.</p><p>Our vision is a collection that feels personal: expressive characters and pieces you love returning to.</p><button class="btn-primary" data-view="collections">EXPLORE COLLECTIONS</button></div><img src="'+ASSETS.logo+'" alt="Anime Kingdom logo"></div>';break;case 'contact':h='<h1>CONTACT ANIME KINGDOM</h1><p><a href="https://www.instagram.com/animekingdom_store/" target="_blank" rel="noopener">Instagram: @animekingdom_store ↗</a></p><p><a class="btn-outline" style="border-color:#ff4545;margin:8px 8px 8px 0" href="https://www.youtube.com/@Animekingdom_store" target="_blank" rel="noopener">SUBSCRIBE ON YOUTUBE ↗</a></p><p>Email placeholder: support@animekingdom.in. Verify before sending. WhatsApp number and business hours were not supplied.</p><form class="ak-form" onsubmit="contactDraft(event)"><label>Name<input name="name" required maxlength="100"></label><label>Email<input name="email" type="email" required></label><label class="wide">Message<textarea name="message" required minlength="10" maxlength="3000"></textarea></label><button class="btn-primary wide">SEND MESSAGE</button></form><p>Your submitted message is stored privately in Anime Kingdom’s database.</p>';break;case 'faq':h='<h1>FREQUENTLY ASKED QUESTIONS</h1>'+[['Is this a live store?','The forms send submissions to Anime Kingdom. Orders, prices and delivery still require seller confirmation.'],['How do I test checkout?','Add a figure, open the cart, and choose Checkout. Select Cash on Delivery or UPI. Orders stay on this device; UPI payments require manual verification.'],['Can I customize a figure?','Submit a brief with size, pose, accessories and a reference photo for seller review.'],['Shipping, returns and care?','Confirm final delivery terms, return eligibility, exchanges and material-specific care with the maker.'],['Are launch emails sent?','No. This demo sends no email, SMS or WhatsApp notifications.']].map(([a,b])=>`<details style="padding:20px 0;border-bottom:1px solid #502562"><summary>${a}</summary><p>${b}</p></details>`).join('');break;case 'shipping':case 'privacy':case 'terms':h=`<h1>${activeView==='shipping'?'SHIPPING & RETURNS':activeView.toUpperCase()}</h1><p style="white-space:pre-wrap">${E(state.policies[activeView]||policies[activeView])}</p>`;break;default:h='<h1>Oops! You entered the wrong dimension.</h1><button class="btn-primary" data-view="home">RETURN TO ANIME KINGDOM</button>'}$('page-view').innerHTML=h;if(['shop','wishlist'].includes(activeView))results();if(activeView==='drops')tick()}
async function paymentProof(file){
 if(!file||!file.size)throw Error('Upload your payment screenshot.');
 if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)throw Error('Choose a PNG, JPG or WebP screenshot no larger than 2 MB.');
 const data=await readFile(file);
 await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve();img.onerror=()=>reject(Error('This image could not be opened. Choose another screenshot.'));img.src=data});
 return data;
}
async function previewPaymentProof(input){
 const preview=$('upi-proof-preview');preview.hidden=true;preview.removeAttribute('src');
 const file=input.files[0];if(!file)return;
 try{const data=await paymentProof(file);if(input.files[0]!==file)return;preview.src=data;preview.hidden=false}catch(error){input.value='';toast(error.message)}
}
